"use client"

import { BRAND } from '@/lib/brand';
import React, { useState, useCallback, useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import { createPortal } from 'react-dom';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useSession, signOut } from 'next-auth/react';
import { 
    getUserNotificationsAction, 
    markNotificationAsReadAction, 
    markAllNotificationsAsReadAction 
} from '@/app/actions';

interface Notification {
    id: string;
    userId: string;
    title: string;
    message: string;
    type: string;
    isRead: boolean;
    createdAt: Date | string;
}

/** `useLayoutEffect` in the browser, `useEffect` on the server, which warns. */
const useBeforePaint = typeof window === 'undefined' ? useEffect : useLayoutEffect;

const TitleBar: React.FC = () => {
    const pathname = usePathname();
    const { data: session } = useSession();
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const drawerRef = useRef<HTMLLIElement>(null);
    const bellRef = useRef<HTMLButtonElement>(null);
    const panelRef = useRef<HTMLDivElement | null>(null);
    /**
     * Where the drawer sits, measured from the bell each time it opens.
     *
     * It is rendered into `document.body` rather than beside the bell, because
     * at phone width `header nav` carries `overflow-x: auto` -- which forces
     * `overflow-y: auto` too, and clipped the drawer to sixteen visible pixels
     * of a 389px panel. The clicks landed and the badge counted down, so the
     * feature was not dead, just invisible (#208).
     *
     * Measured rather than assumed: the header is sticky and its height changes
     * with the viewport, so a hard-coded offset would drift.
     */
    const [anchor, setAnchor] = useState<{ top: number; right: number; width: number } | null>(null);

    const pageTitles: { [key: string]: string } = {
        '/book': 'Book Flight',
        '/travelguide': 'Travel Guide',
        '/profile': 'Profile',
        '/flights': 'Flight Status',
        '/admin': 'Admin Dashboard',
        '/admin/travelguide': 'Manage City Guides',
    };

    const pageTitle = pageTitles[pathname] || '';
    const userAvatar = session?.user?.image || "/img/my-profile-photo.jpg";
    const isAdmin = session?.user?.role === 'ADMIN' && session.user.staffMfaVerified;

    // Set while the document is going away, so a poll that dies with it can be
    // told apart from one that failed on its own.
    const leavingPage = useRef(false);

    useEffect(() => {
        const onPageHide = () => { leavingPage.current = true; };
        // `pagehide` also fires when the document goes into the back-forward
        // cache, where this component and its effects are kept alive. Coming
        // back with Back fires `pageshow` rather than remounting, so without
        // this the flag would stay set and silence every later failure for the
        // rest of the page's life.
        const onPageShow = () => { leavingPage.current = false; };

        window.addEventListener('pagehide', onPageHide);
        window.addEventListener('pageshow', onPageShow);
        return () => {
            window.removeEventListener('pagehide', onPageHide);
            window.removeEventListener('pageshow', onPageShow);
        };
    }, []);

    // Fetch immediately on mount / route change, and set up 3s polling interval
    useEffect(() => {
        // Whether *this* poll's result is still wanted. A server action takes no
        // abort signal, so the teardown is what gets tracked rather than the
        // request -- which is the distinction that matters: a rejection arriving
        // after the effect was cleaned up, or while the page is being replaced,
        // lost nothing and is not news. Anything else is (#195, #212).
        //
        // Matching the rejection's message instead could not tell a navigation
        // from a dead server: browsers say `Failed to fetch` for both.
        let active = true;

        const poll = async () => {
            if (!session?.user) {
                setNotifications([]);
                return;
            }
            try {
                const notifs = await getUserNotificationsAction();
                if (active) setNotifications(notifs as Notification[]);
            } catch (err) {
                if (!active || leavingPage.current) return;
                console.error("Failed to load notifications:", err);
            }
        };

        poll();
        const interval = setInterval(poll, 3000);
        return () => {
            active = false;
            clearInterval(interval);
        };
    }, [session, pathname]);

    /**
     * Escape closes the drawer from anywhere, and hands focus back.
     *
     * On the document rather than the panel, because focus leaves the panel the
     * moment anyone tabs: with the handler on the panel alone, Escape stopped
     * working and the drawer sat open over the page with the bell five stops
     * away.
     *
     * Focus is only restored here. Restoring it after an outside click fought
     * the browser and lost -- the default mousedown action blurs to the body
     * after React has run, so the effect's work was undone a frame later, and
     * the same guard stole focus to the bell on a cold page load where nothing
     * was focused yet.
     */
    useEffect(() => {
        if (!isOpen) return;
        const closeOnEscape = (event: KeyboardEvent) => {
            if (event.key !== 'Escape') return;
            setIsOpen(false);
            bellRef.current?.focus();
        };
        document.addEventListener('keydown', closeOnEscape);
        return () => document.removeEventListener('keydown', closeOnEscape);
    }, [isOpen]);

    /**
     * Focused as it mounts, rather than from an effect on `isOpen`.
     *
     * The panel does not exist at the moment `isOpen` flips -- it waits a render
     * for the bell to be measured -- so an effect keyed on `isOpen` finds a null
     * ref and silently does nothing.
     */
    const attachPanel = useCallback((node: HTMLDivElement | null) => {
        panelRef.current = node;
        node?.focus();
    }, []);

    // Keep the drawer under the bell as the page scrolls or the window resizes.
    // Placed before paint, or reopening after the bell has moved shows a frame
    // at the old position; guarded because `useLayoutEffect` warns on the
    // server, where this component is still rendered.
    useBeforePaint(() => {
        if (!isOpen) {
            // Cleared, or reopening paints one frame at the old position.
            setAnchor(null);
            return;
        }

        const place = () => {
            const rect = bellRef.current?.getBoundingClientRect();
            if (!rect) return;
            const viewport = window.innerWidth;
            const measuredRight = Math.max(8, viewport - rect.right);
            // Wide enough to read, but never wider than the viewport itself.
            const floor = Math.min(240, viewport - 16);
            const width = Math.max(floor, Math.min(320, viewport - measuredRight - 8));
            // Then pull it back rightwards if that width would push its left
            // edge off screen. Clamping the width alone is not enough: the
            // floor can beat the space the inset leaves, and at 320px -- where
            // the bell sits in a horizontally scrolled nav, so the inset is
            // large -- the panel started at -65 with no way to scroll to it.
            const right = Math.min(measuredRight, Math.max(8, viewport - width - 8));

            setAnchor({ top: rect.bottom + 8, right, width });
        };

        place();
        window.addEventListener('resize', place);
        // Capturing, so a scroll inside any container still repositions it.
        window.addEventListener('scroll', place, true);
        return () => {
            window.removeEventListener('resize', place);
            window.removeEventListener('scroll', place, true);
        };
    }, [isOpen]);

    // Click outside to close notifications drawer
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            const target = event.target as Node;
            // The panel is no longer inside `drawerRef`, so "outside" has to
            // mean outside both, or every click within the drawer closes it.
            const insideTrigger = drawerRef.current?.contains(target);
            const insidePanel = panelRef.current?.contains(target);
            if (!insideTrigger && !insidePanel) {
                setIsOpen(false);
            }
        };

        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen]);

    const unreadCount = useMemo(() => {
        return notifications.filter(n => !n.isRead).length;
    }, [notifications]);

    const handleMarkAsRead = async (id: string) => {
        try {
            await markNotificationAsReadAction(id);
            setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
        } catch (err) {
            console.error("Failed to mark as read:", err);
        }
    };

    const handleMarkAllAsRead = async () => {
        try {
            await markAllNotificationsAsReadAction();
            setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
        } catch (err) {
            console.error("Failed to mark all as read:", err);
        }
    };

    return (
        <header className={pathname?.startsWith('/admin') ? 'admin-header' : ''}>
            <div className="logo">
                <Link href="/" style={{ display: 'flex', alignItems: 'center', gap: '8px', textDecoration: 'none' }}>
                    {/* Decorative: the name follows in text inside the same
                        link, so alt would make the link read "Mona Airways
                        Mona Airways". The mark carries no wordmark of its own. */}
                    <img src="/img/logo.svg" alt="" width="32" height="32" />
                    <span style={{ fontWeight: 'bold', fontSize: '1.2rem' }}>{BRAND.name}</span>
                </Link>
                <span>{pageTitle}</span>
            </div>
            <nav>
                <ul style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
                    {!pathname?.startsWith('/admin') && (
                        <>
                            <li className={pathname === '/book' ? 'selected' : ''}>
                                <Link href="/book">Book Flight</Link>
                            </li>
                            <li className={pathname === '/travelguide' ? 'selected' : ''}>
                                <Link href="/travelguide">Travel Guide</Link>
                            </li>
                            <li className={pathname === '/flights' ? 'selected' : ''}>
                                <Link href="/flights">Flight Status</Link>
                            </li>
                        </>
                    )}

                    {isAdmin && (
                        <li className={pathname === '/admin' ? 'selected' : ''}>
                            <Link href="/admin">Admin</Link>
                        </li>
                    )}

                    {session ? (
                        <li style={{ display: 'flex', alignItems: 'center', gap: '16px', position: 'relative' }} ref={drawerRef}>
                            {/* Notification Bell Container */}
                            <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                                <button 
                                    ref={bellRef}
                                    onClick={() => setIsOpen(!isOpen)}
                                    aria-label="Toggle notifications"
                                    aria-haspopup="dialog"
                                    aria-expanded={isOpen}
  createdAt          DateTime       @default(now())

  @@index([providerIntentId])
  @@index([paymentAttemptId])
}

model Booking {
  id              Int           @id @default(autoincrement())
  createdAt       DateTime      @default(now())
  status          BookingStatus @default(CONFIRMED)
  paymentIntentId String?       @unique
  /// The booking total in minor units. Null for bookings taken before this
  /// column existed, which fall back to the flight's catalogue price.
  totalPriceCents Int?
  currency        String        @default("USD")
  idempotencyKey  String?

  userId String?
  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)

  passengers    Passenger[]
  legs          ItineraryLeg[]
  statusChanges BookingStatusChange[]
  rebookings    BookingRebooking[]

  @@unique([userId, idempotencyKey])
}

/// One move between booking states, and the only record of the ones a booking
/// is no longer in.
///
/// Append-only, enforced by a trigger rather than by convention: cancellation,
/// disruption and refunds all have to be auditable, and a table that reaches
/// this state only while every caller cooperates is not an audit trail (#76).
/// Rows go when their booking goes -- the history of a booking that does not
/// exist has no subject, and blocking that cascade would make a booking
/// undeletable.
model BookingStatusChange {
  id          String         @id @default(cuid())
  bookingId   Int
  booking     Booking        @relation(fields: [bookingId], references: [id], onDelete: Cascade)
  /// Null for the row that records the booking coming into existence.
  from        BookingStatus?
  to          BookingStatus
  reason      String?
  /// What this change owed the customer back, in minor units. Null where the
  /// change did not refund; zero is a different and real answer, since a
  /// cancellation inside the cut-off refunds nothing (#76).
  refundCents Int?
  /// Orders changes made in the same transaction, which `createdAt` cannot:
  /// it is transaction start time, so two changes there share an instant.
  /// A `BigInt` in the client, so a row handed straight to a client component
  /// fails to serialise -- select what you need rather than the whole row.
  sequence    BigInt         @default(autoincrement())
  /// Who caused it. Null for a customer acting on their own booking, and for a
  /// change nothing attributes.
  actorUserId String?
  actor       User?          @relation(fields: [actorUserId], references: [id], onDelete: SetNull)
  paymentRefund PaymentRefund?
  rebooking   BookingRebooking?
  createdAt   DateTime       @default(now())

  @@index([bookingId, createdAt])
  @@index([bookingId, sequence])
}

/// The immutable audit event for replacing one or more disrupted itinerary
/// legs while retaining the booking, passengers, reference and captured fare.
/// The status change records the customer-visible DISRUPTED -> CONFIRMED move;
/// this row records why it happened and which legs replaced which.
model BookingRebooking {
import type { Metadata } from 'next';
import React from "react";
import PointsActivityService from "@/lib/PointsActivityService";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { flightRouteInclude, withLegRouteLabels } from "@/lib/flightRoute";
import ProfileClient from "@/components/ui/ProfileClient";
import { serverRenderTime } from "@/lib/serverClock";
import { safePassengerSelect } from "@/lib/passengerDataAccess";
import { activeItineraryLegWhere, orderedLegs } from '@/lib/bookingItinerary';
import { ItineraryReplacementSearch } from '@/lib/itineraryReplacementSearch';
import {
  accountTimeZoneChoices,
  DEFAULT_ACCOUNT_TIME_ZONE,
  normalizeAccountTimeZone,
} from '@/lib/accountTimeZone';

export const metadata: Metadata = {
    title: 'Your profile',
    description: 'Your bookings, seats, status points and saved travel guides.',
};

export const dynamic = 'force-dynamic';

export default async function ProfilePage() {
  const session = await getServerSession(authOptions);
  // Read rather than called in the markup below: see lib/serverClock.
  const renderedAt = await serverRenderTime();

  if (!session?.user) {
    return <div className="p-8 text-center text-xl" style={{ marginTop: '100px', color: 'black' }}>Please log in to view your profile.</div>;
  }

  const user = session.user;
  const userId = user.id;
  const userName = user.name || "Traveler";
  const userAvatar = user.image || "https://i.pravatar.cc/150?u=" + userId;
  const account = await prisma.user.findUniqueOrThrow({
    where: { id: userId },
    select: { timeZone: true },
  });
  const accountTimeZone = normalizeAccountTimeZone(account.timeZone)
    ?? DEFAULT_ACCOUNT_TIME_ZONE;

  const userBookings = await prisma.booking.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
    include: {
      // Read the itinerary through its legs, so a round trip needs no change
      // here beyond rendering more than one (#69).
      legs: {
        where: activeItineraryLegWhere,
        include: {
          flight: { include: flightRouteInclude },
          // The seat is held per leg, so a round trip has a different one on
          // each; Passenger.seatNumber only ever described the outbound.
          seatAssignments: {
            select: {
              passengerId: true,
              seatNumber: true,
              cabinClass: true,
              // A released seat shows as released rather than as a number that
              // is no longer this customer's (#76).
              releasedAt: true,
            },
          },
        },
        orderBy: { sequence: 'asc' },
      },
      passengers: { select: safePassengerSelect },
      statusChanges: {
        where: { to: 'CANCELLED' },
        orderBy: { sequence: 'desc' },
        take: 1,
        select: {
          createdAt: true,
          refundCents: true,
          paymentRefund: {
            select: { amountCents: true, status: true },
          },
        },
      },
    },
  });

  const replacementSearch = new ItineraryReplacementSearch();
  const replacementOptions = Object.fromEntries(await Promise.all(
    userBookings
      .filter(booking => booking.status === 'DISRUPTED')
      .map(async booking => [
        booking.id,
        await replacementSearch.forBooking({ bookingId: booking.id, userId }),
      ] as const),
  ));

  // A booking exists only after capture, but the durable attempt remains the
  // authoritative payment record. Select only captured rows, then project a
  // receipt below without sending Stripe IDs, checkout IDs or fingerprints to
  // the client (#75).
  const providerIntentIds = userBookings.flatMap(booking =>
    booking.paymentIntentId ? [booking.paymentIntentId] : []
  );
  const capturedPayments = providerIntentIds.length > 0
    ? await prisma.paymentAttempt.findMany({
        where: {
          providerIntentId: { in: providerIntentIds },
          status: 'CAPTURED',
          capturedAt: { not: null },
        },
        select: {
          providerIntentId: true,
          amountCents: true,
          currency: true,
          capturedAt: true,
        },
      })
    : [];
  const capturedPaymentByIntent = new Map(
    capturedPayments.flatMap(payment => payment.providerIntentId && payment.capturedAt
      ? [[payment.providerIntentId, {
          amountCents: payment.amountCents,
          currency: payment.currency,
          capturedAt: payment.capturedAt,
        }] as const]
      : []
    )
  );

  const userFavorites = await prisma.userFavorite.findMany({
    where: { userId },
    include: { cityGuide: true },
