    /// airline cancelled, which on a round trip is often not the first (#76).
    status?: string;
    firstClassRows?: number | null;
    businessRows?: number | null;
    premiumEconomyRows?: number | null;
    economyRows?: number | null;
    seatPattern?: string | null;
}

interface Passenger {
    id: string;
    firstName: string;
    lastName: string;
    gender: string;
}

interface SeatAssignment {
    passengerId: string;
    seatNumber: string;
    cabinClass: string;
    releasedAt?: Date | string | null;
}

interface BookingLeg {
    id: number;
    sequence: number;
    flight: Flight | null;
    seatAssignments?: SeatAssignment[];
}

interface Booking {
    id: number;
    createdAt: Date | string;
    status: string; // "CONFIRMED", "DISRUPTED" or "CANCELLED"
    totalPriceCents: number | null;
    // The itinerary. One leg today; a round trip adds the inbound (#69).
    legs: BookingLeg[];
    passengers: Passenger[];
    paymentReceipt?: {
        amountCents: number;
        currency: string;
        paidAt: Date | string;
    } | null;
    statusChanges?: Array<{
        refundCents: number | null;
        paymentRefund: {
            amountCents: number;
