const customJestConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/$1',
  },
  testPathIgnorePatterns: ['<rootDir>/.next/', '<rootDir>/node_modules/', '<rootDir>/e2e/'],
}

// Matches the extensions Jest's default testMatch would pick up, so a
// `.database.test.tsx` cannot fall through to the parallel project and quietly
// reintroduce the collisions this split exists to remove.
const DATABASE_TESTS = '\\.database\\.test\\.[jt]sx?$'

/**
 * Two projects, because the database tests share one Postgres and must not run
 * beside each other.
 *
 * Several assert against whole tables on purpose — `seatAssignmentCoverage`
 * proves the invariant #137 relied on holds for data the test did not create —
 * so a fixture another file is holding open gets counted and the run fails on
 * work that is not its own (#155). Running them one file at a time removes the
 * overlap without weakening a single assertion.
 *
 * `npm run test:database` passes `--runInBand`, which is what actually
 * serialises them; splitting the projects is what lets it apply to those files
 * alone. It costs about 3s on those 9 files, and around 9s on the suite as a
 * whole once the two phases no longer interleave — roughly 21s to 31s. Worth
 * it for a result that does not depend on which files happen to overlap.
 *
 * createJestConfig is called this way to ensure next/jest can load the Next.js
 * config, which is async.
 */
module.exports = async () => ({
  projects: [
    await createJestConfig({
      ...customJestConfig,
      displayName: 'unit',
      testPathIgnorePatterns: [...customJestConfig.testPathIgnorePatterns, DATABASE_TESTS],
    })(),
    await createJestConfig({
      ...customJestConfig,
      displayName: 'database',
      testMatch: ['**/*.database.test.?(ts|tsx|js|jsx)'],
      // Refuses the run rather than letting it interfere quietly (#215).
      globalSetup: '<rootDir>/jest.database-setup.js',
    })(),
  ],
})
/**
 * Refuses to run the database project in parallel.
 *
 * These files share one Postgres and several assert against whole tables, so a
 * fixture another file is holding open gets counted and the run fails on work
 * that is not its own (#155). Splitting them into their own project is what
 * lets them be serialised; `--runInBand` in `npm run test:database` is what
 * actually serialises them.
 *
 * That left the guarantee resting on which command someone typed, and the
 * dangerous one is shorter: `npx jest --selectProjects database` looks
 * equivalent and runs the files in parallel, reproducing exactly the
 * interference the split removed. It cost a full afternoon of chasing failures
 * that looked like real regressions (#215).
 *
 * Jest has no per-project `maxWorkers`, so this cannot be configured away — but
 * a project's `globalSetup` is handed the resolved global config, which is
 * enough to refuse.
 */
function assertSerialised(globalConfig) {
    const maxWorkers = globalConfig?.maxWorkers ?? 1;

    if (maxWorkers > 1) {
        throw new Error(
            `The database test project must run one file at a time, and this run has `
            + `maxWorkers=${maxWorkers}. These files share one database and several `
            + `assert against whole tables, so in parallel they count each other's `
            + `fixtures and fail on work that is not their own (#155).\n\n`
            + `Use \`npm run test:database\`, which passes --runInBand, or add `
            + `--runInBand yourself.`
        );
    }
}

module.exports = async function databaseGlobalSetup(globalConfig) {
    assertSerialised(globalConfig);
};

