import { Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';

const createdBookingIds: number[] = [];

async function createBooking() {
    const booking = await prisma.booking.create({ data: {} });
    createdBookingIds.push(booking.id);
    return booking;
