export async function bookFlightAction(bookingData: {
    flightIds: number[];
    passengers: PassengerInput[];
    idempotencyKey: string;
}) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error("Unauthorized");
    const parsed = parseActionInput(bookingRequestSchema, bookingData);
    if (!parsed.ok) return parsed;
    bookingData = parsed.data as typeof bookingData;

    let result;
    let capture;
    const paymentService = new CheckoutPaymentService(createStripePaymentProvider());
    try {
        const payment = await paymentService.startPayment({
            checkoutId: bookingData.idempotencyKey,
            flightIds: bookingData.flightIds,
            passengers: bookingData.passengers.map(passenger => ({
                seatNumbers: passenger.seatNumbers,
                cabinClass: passenger.cabinClass as 'ECONOMY' | 'PREMIUM_ECONOMY' | 'BUSINESS' | 'FIRST',
            })),
            userId,
        });
        if (payment.status !== 'AUTHORIZED' && payment.status !== 'CAPTURED') {
            return actionValidationFailure('Payment authorization is required before booking.');
        }

        result = await flightBookingService.bookFlight({
            flightIds: bookingData.flightIds,
            userId,
            passengers: bookingData.passengers,
            idempotencyKey: bookingData.idempotencyKey,
            paymentIntentId: payment.providerIntentId,
        });
        try {
            capture = await paymentService.capturePayment({
                userId,
                checkoutId: bookingData.idempotencyKey,
                bookingId: result.id,
            });
        } catch {
            // The booking transaction has committed at this point. Whatever
            // failed at the provider/settlement boundary, the truthful and
            // safe recovery state is a secured booking with capture pending.
            throw new PaymentCaptureIncompleteError();
        }

            // Retain passenger data until the trip ends, which is the last leg.
            const lastDeparture = flights
                .map(flight => flight.departureDate)
                .reduce((latest, date) => (date > latest ? date : latest));
            const sensitiveDataExpiresAt = getPassengerDataRetentionDeadline(lastDeparture);

            const protectedPassengers = passengers.map(passenger => {
                const id = randomUUID();
                const dateOfBirth = passenger.dateOfBirth.slice(0, 10);
                return {
                    id,
                    firstName: passenger.firstName,
                    lastName: passenger.lastName,
                    dateOfBirthEncrypted: encryptPassengerData(dateOfBirth, {
                        passengerId: id,
                        field: 'dateOfBirth',
                    }),
                    passportNumberEncrypted: encryptPassengerData(passenger.passportNumber, {
                        passengerId: id,
                        field: 'passportNumber',
                    }),
                    sensitiveDataExpiresAt,
                    gender: passenger.gender,
                    // A traveller is a person, not a seat. Where they sit is a
                    // SeatAssignment per leg, written below (#137).
                };
            });

            const booking = await tx.booking.create({
                data: {
                    userId,
                    totalPriceCents: total.cents,
                    legs: {
                        create: flightIds.map((flightId, index) => ({
                            sequence: index + 1,
                            flightId,
                        })),
                    },
                    paymentIntentId,
                    idempotencyKey,
                    passengers: {
                        create: protectedPassengers
                    }
                },
                include: {
                    passengers: { select: safePassengerSelect },
                    legs: {
                        where: activeItineraryLegWhere,
                        orderBy: { sequence: 'asc' },
                    }
                }
            });

            // Seat assignments need each leg's identity, so they follow the
            // booking. Written from the same arrays the legs and passengers came
            // from, so the three cannot disagree.
            await tx.seatAssignment.createMany({
                data: booking.legs.flatMap((leg, legIndex) => (
                    protectedPassengers.map((passenger, passengerIndex) => ({
                        passengerId: passenger.id,
                        legId: leg.id,
                        flightId: leg.flightId,
                        seatNumber: passengers[passengerIndex].seatNumbers[legIndex],
                        // The cabin belongs to the seat, and the request is
                        // what says which cabin was bought.
                        cabinClass: passengers[passengerIndex].cabinClass,
                    }))
                )),
            });

