interface CancelledLeg {
    id: number;
    seatAssignments?: Array<{
        passengerId: string;
        cabinClass: string;
    }>;
}

interface ItineraryRebookingDialogProps {
    bookingId: number;
    passengers: RebookingPassenger[];
    cancelledLegs: CancelledLeg[];
    groups: ReplacementFlightGroup[];
    onSuccess: () => void;
}

const seatKey = (legId: number, passengerId: string) => `${legId}:${passengerId}`;

export default function ItineraryRebookingDialog({
    bookingId,
    passengers,
    cancelledLegs,
    groups,
    onSuccess,
}: ItineraryRebookingDialogProps) {
    const router = useRouter();
    const triggerRef = useRef<HTMLButtonElement | null>(null);
    const dialogRef = useRef<HTMLElement | null>(null);
    const firstFlightRef = useRef<HTMLSelectElement | null>(null);
    const errorRef = useRef<HTMLDivElement | null>(null);
    const [open, setOpen] = useState(false);
    const [selectedFlights, setSelectedFlights] = useState<Record<number, number>>({});
    const [selectedSeats, setSelectedSeats] = useState<Record<string, string>>({});
    const [occupiedByFlight, setOccupiedByFlight] = useState<Record<number, string[]>>({});
    const [error, setError] = useState<string | null>(null);
    booking,
    groups,
    onSuccess,
}: {
    booking: Booking;
    groups: ReplacementFlightGroup[];
    onSuccess: () => void;
}) {
    const bookingId = booking.id;
    const headingId = `replacement-flights-${bookingId}`;
    const allLegsHaveOptions = groups.length > 0
        && groups.every(group => group.flights.length > 0);

    return (
        <section
            className="replacement-flight-preview"
            aria-labelledby={headingId}
        >
            <h3 id={headingId}>
                Replacement flights within 3 days
                <span className="sr-only"> for booking {bookingId}</span>
            </h3>
            {groups.map(group => (
                <div className="replacement-flight-group" key={group.fromLegId}>
                    <h4>
                        {group.originalFlightNumber}: {group.from} → {group.to}
                    </h4>
                    {group.flights.length > 0 && (
                        <ul>
                            {group.flights.map(flight => {
                                const departure = flightDeparture(flight);
                                return (
                                    <li key={flight.id}>
                                        <strong>{flight.airline} {flight.flightNumber}</strong>
                                        <span>{flight.from} → {flight.to}</span>
                                        <span>
                                            {departure.readableDate} at {departure.time} {departure.zoneLabel}
                                        </span>
                                    </li>
                                );
                            })}
                        </ul>
                    )}
                </div>
            ))}
            <p className="replacement-flight-guidance">
                {allLegsHaveOptions
                    ? 'Your original fare is protected. Choose replacement flights and seats below, or cancel for a full refund.'
                    : 'No complete replacement itinerary is available within three days. Contact support, or cancel for a full refund.'}
            </p>
            {allLegsHaveOptions && (
                <ItineraryRebookingDialog
                    bookingId={booking.id}
                    passengers={booking.passengers}
                    cancelledLegs={booking.legs.filter(leg => leg.flight?.status === 'CANCELLED')}
                    groups={groups}
                    onSuccess={onSuccess}
                />
            )}
        </section>
    );
}

